class Solution:
    def robotWithString(self, s: str) -> str:

        n=len(s)
        suf=[0]*n
        suf[n-1]=n-1
        for j in range(n-2,-1,-1):
            if s[j]<=s[suf[j+1]]:
                suf[j]=j

            else:
                suf[j]=suf[j+1]


        def get(i):
            idx=suf[i]

            return idx

        n=len(s)
        idx=0
        ans = ''

        i=0
        stack = []
        while 1:

            if idx < n-1:

                idx = get(i)
                while stack and stack[-1] <= s[idx]:
                    ans += stack.pop()



                for ii in range(i,idx + 1):
                    stack.append(s[ii])

                i=idx+1


            else:

                while stack:
                    ans += stack.pop()
                break

        return ans


s="bydizfve"
#s='zza'
s=""
res=Solution().robotWithString(s)
print(res)
